	/* @Test */
	public void testTitleOnly()
    {
		createProgram();
		TraceRmiLaunchOffer offer = new TestScriptTraceRmiLaunchOffer(program, """
				@title Test
				""");

		using (ResultAndClient rac = launchNoErr(offer))
{
			assertEquals(Map.ofEntries(
				Map.entry("Shell", rac.mockSession())),
				rac.result.sessions());
		}
	}

